#include <stdint.h>
#include <stdio.h>

typedef struct {
    uint32_t frequency;
    uint16_t duty_cycle;
    uint8_t channel;
} pwm_config_t;

void setup_pwm(pwm_config_t *config) {
    printf("Setting PWM: freq=%lu, duty=%u, ch=%u\n",
           config->frequency, config->duty_cycle, config->channel);
}

int main(void) {
    pwm_config_t pwm;
    pwm.frequency = 1000;
    pwm.channel = 0;
    // duty_cycle not initialized
    setup_pwm(&pwm);
    return 0;
}
